suite(B) ->
    M=ssl_cipher_format:suite_bin_to_map(B),
    [observe({map,B},fun()->ssl_cipher_format:suite_bin_to_map(B) end),
     observe({bin,B},fun()->ssl_cipher_format:suite_map_to_bin(M) end),
     observe({legacy_bin,B},fun()->ssl_cipher_format:suite_legacy(B) end),
     observe({legacy_map,B},fun()->ssl_cipher_format:suite_legacy(M) end),
     observe({rfc,B},fun()->ssl_cipher_format:suite_map_to_str(M) end),
     observe({openssl,B},fun()->ssl_cipher_format:suite_map_to_openssl_str(M) end)].
message(M) ->
    [observe({encode,M},fun()->ssh_message:encode(M) end),
     observe({decode,M},fun()->ssh_message:decode(ssh_message:encode(M)) end)].
curve(Name) ->
    Oid=ssh_message:ssh_curvename2oid(Name),
    [observe({oid,Name},fun()->ssh_message:ssh_curvename2oid(Name) end),
     observe({curve,Name},fun()->ssh_message:oid2ssh_curvename(Oid) end),
     observe({algorithm,Name},fun()->ssh_message:oid2ssh_curve_algo(Oid) end)].
observe(Name, Fun) ->
    try {Name, {returned, Fun()}}
    catch Class:Reason:Stack -> {Name, {caught, Class, Reason, Stack}}
    end.

skip(B,N,little) -> case B of <<_:N/little,T/bitstring>> -> {ok,T}; _ -> no end;
skip(B,N,signed) -> case B of <<_:N/signed,T/bitstring>> -> {ok,T}; _ -> no end;
skip(B,N,native) -> case B of <<_:N/native,T/bitstring>> -> {ok,T}; _ -> no end;
skip(B,N,unit8) -> case B of <<_:N/unit:8-little,T/bitstring>> -> {ok,T}; _ -> no end.

wide(B,160) -> case B of <<V:160,T/bitstring>> -> {V,T}; _ -> no end;
wide(B,256) -> case B of <<V:256/little,T/bitstring>> -> {V,T}; _ -> no end;
wide(B,521) -> case B of <<V:521/signed,T/bitstring>> -> {V,T}; _ -> no end;
wide(B,4096) -> case B of <<V:4096,T/bitstring>> -> {V,T}; _ -> no end.
